{"command":"create","path":"/app/solution.py","file_text":"import json
import re
from collections import OrderedDict, deque
from dataclasses import dataclass
from typing import Any, Dict, List, Optional, Tuple


_SECTION_RE = re.compile(r"^\[(?P<id>[^\]]+)\]\s*$")
_CHOICE_RE = re.compile(r"^\s*(?P<num>\d+)\.\s*(?P<body>.+?)\s*$")


@dataclass
class Node:
    id: str
    text: str = ""
    speaker: str = ""
    type: str = "line"  # 'line' or 'choice'

    def to_dict(self) -> Dict[str, str]:
        return {"id": self.id, "text": self.text, "speaker": self.speaker, "type": self.type}


@dataclass
class Edge:
    source: str
    target: str
    text: str = ""

    def to_dict(self) -> Dict[str, str]:
        return {"from": self.source, "to": self.target, "text": self.text}


def _split_arrow(line: str) -> Tuple[str, Optional[str]]:
    if "->" not in line:
        return line.strip(), None
    left, right = line.rsplit("->", 1)
    return left.strip(), right.strip() or None


def _ensure_node(nodes: "OrderedDict[str, Node]", node_id: str, *, node_type: str = "line") -> Node:
    node = nodes.get(node_id)
    if node is None:
        node = Node(id=node_id, type=node_type)
        nodes[node_id] = node
    else:
        # If we learned later that it's a choice node, upgrade.
        if node.type != node_type and node_type == "choice":
            node.type = "choice"
            node.speaker = ""
            node.text = ""
    return node


def _parse_section_body(section_id: str, lines: List[str], nodes: "OrderedDict[str, Node]", edges: List[Edge]) -> None:
    cleaned = [ln.strip() for ln in lines if ln.strip() and not ln.strip().startswith("#")]
    if not cleaned:
        _ensure_node(nodes, section_id, node_type="line")
        return

    is_choice = all(_CHOICE_RE.match(_split_arrow(ln)[0]) is not None for ln in cleaned)

    if is_choice:
        _ensure_node(nodes, section_id, node_type="choice")
        for ln in cleaned:
            left, target = _split_arrow(ln)
            m = _CHOICE_RE.match(left)
            if not m:
                continue
            choice_text = m.group("body").strip()
            if target:
                edges.append(Edge(source=section_id, target=target, text=choice_text))
                _ensure_node(nodes, target)
        return

    # Dialogue (one or many lines). If multiple dialogue lines exist in the section,
    # we model them as a linear chain of synthetic nodes.
    prev_id: Optional[str] = None
    for i, ln in enumerate(cleaned):
        left, target = _split_arrow(ln)

        if ":" in left:
            speaker, text = left.split(":", 1)
            speaker = speaker.strip()
            text = text.strip()
        else:
            speaker, text = "", left.strip()

        node_id = section_id if i == 0 else f"{section_id}__{i+1}"
        node = _ensure_node(nodes, node_id, node_type="line")
        node.speaker = speaker
        node.text = text

        if prev_id is not None:
            edges.append(Edge(source=prev_id, target=node_id, text=""))

        prev_id = node_id

        if target:
            edges.append(Edge(source=node_id, target=target, text=""))
            _ensure_node(nodes, target)
            prev_id = None  # explicit transition ends this chain


def _reachable_from(start: str, edges: List[Edge]) -> set:
    adj: Dict[str, List[str]] = {}
    for e in edges:
        adj.setdefault(e.source, []).append(e.target)

    seen = set()
    q = deque([start])
    while q:
        cur = q.popleft()
        if cur in seen:
            continue
        seen.add(cur)
        for nxt in adj.get(cur, []):
            if nxt not in seen:
                q.append(nxt)
    return seen


def _prune_unreachable(graph: Dict[str, Any]) -> Dict[str, Any]:
    nodes = graph.get("nodes", [])
    edges = graph.get("edges", [])
    if not nodes:
        return graph

    start = nodes[0]["id"]
    reach = _reachable_from(start, [Edge(e["from"], e["to"], e.get("text", "")) for e in edges])

    nodes2 = [n for n in nodes if n["id"] in reach]
    edges2 = [e for e in edges if e["from"] in reach and e["to"] in reach]

    return {"nodes": nodes2, "edges": edges2}


def validate_graph(graph: Dict[str, Any]) -> List[str]:
    errors: List[str] = []

    nodes = graph.get("nodes", [])
    edges = graph.get("edges", [])

    node_ids = [n.get("id") for n in nodes]
    if not node_ids:
        return ["Graph has no nodes"]

    node_set = set(node_ids)

    for e in edges:
        if e.get("from") not in node_set:
            errors.append(f"Edge from missing node '{e.get('from')}'")
        if e.get("to") not in node_set:
            errors.append(f"Edge targets missing node '{e.get('to')}'")

    # Reachability from first node.
    start = node_ids[0]
    reach = _reachable_from(start, [Edge(e["from"], e["to"], e.get("text", "")) for e in edges])
    unreachable = [nid for nid in node_ids if nid not in reach]
    if unreachable:
        errors.append(f"Unreachable nodes from start '{start}': {', '.join(unreachable)}")

    return errors


def to_dot(graph: Dict[str, Any]) -> str:
    nodes = graph.get("nodes", [])
    edges = graph.get("edges", [])

    def esc(s: str) -> str:
        return s.replace("\\", "\\\\").replace('"', '\\"')

    out: List[str] = ["digraph Dialogue {", "  rankdir=LR;", "  node [fontname=Helvetica];"]

    for n in nodes:
        nid = n.get("id", "")
        ntype = n.get("type", "line")
        speaker = n.get("speaker", "") or ""
        text = n.get("text", "") or ""

        if ntype == "choice":
            label = f"{nid}"
            shape = "diamond"
        else:
            label = nid
            if speaker and text:
                label = f"{nid}\\n{speaker}: {text}"
            elif text:
                label = f"{nid}\\n{text}"
            shape = "box"

        out.append(f"  \"{esc(nid)}\" [shape={shape}, label=\"{esc(label)}\"]; ")

    for e in edges:
        src = e.get("from", "")
        dst = e.get("to", "")
        label = e.get("text", "") or ""
        if label:
            out.append(f"  \"{esc(src)}\" -> \"{esc(dst)}\" [label=\"{esc(label)}\"]; ")
        else:
            out.append(f"  \"{esc(src)}\" -> \"{esc(dst)}\";")

    out.append("}")
    return "\n".join(out)


def parse_script(text: str) -> Dict[str, Any]:
    """Parse a bracketed-section dialogue script into a JSON-serializable graph.

    Returns: {"nodes": [...], "edges": [...]}
    """
    nodes: "OrderedDict[str, Node]" = OrderedDict()
    edges: List[Edge] = []

    current_id: Optional[str] = None
    current_lines: List[str] = []

    def flush() -> None:
        nonlocal current_id, current_lines
        if current_id is None:
            return
        _parse_section_body(current_id, current_lines, nodes, edges)
        current_id = None
        current_lines = []

    for raw in text.splitlines():
        line = raw.rstrip("\n")
        m = _SECTION_RE.match(line.strip())
        if m:
            flush()
            current_id = m.group("id").strip()
            current_lines = []
            # Pre-create so first node ordering is preserved.
            _ensure_node(nodes, current_id)
            continue
        if current_id is not None:
            current_lines.append(line)

    flush()

    # Ensure an explicit End node exists if referenced.
    referenced = {e.target for e in edges}
    if "End" in referenced and "End" not in nodes:
        nodes["End"] = Node(id="End", type="line", speaker="", text="")

    graph = {
        "nodes": [n.to_dict() for n in nodes.values()],
        "edges": [e.to_dict() for e in edges],
    }

    # Prune unreachable nodes to satisfy constraint (1).
    graph = _prune_unreachable(graph)
    return graph


def main() -> int:
    with open("/app/script.txt", "r", encoding="utf-8") as f:
        text = f.read()

    graph = parse_script(text)
    errors = validate_graph(graph)
    if errors:
        raise SystemExit("Validation failed:\n" + "\n".join(f"- {e}" for e in errors))

    with open("/app/dialogue.json", "w", encoding="utf-8") as f:
        json.dump(graph, f, indent=2, ensure_ascii=False)

    with open("/app/dialogue.dot", "w", encoding="utf-8") as f:
        f.write(to_dot(graph))

    return 0


if __name__ == "__main__":
    raise SystemExit(main())
"}

